WITH chosen AS (SELECT regexp_replace(lower(domain),'^www\.','') AS canonical FROM shopify_store_index WHERE status='discovered' GROUP BY 1 ORDER BY md5(regexp_replace(lower(domain),'^www\.','') || ':index-v2-1k') LIMIT 4500) SELECT jsonb_agg(jsonb_build_object('domain',s.domain,'id',s.id,'source',coalesce(s.discovery_source,s.source),'updated_at',s.updated_at) ORDER BY s.domain) AS seed_rows FROM shopify_store_index s JOIN chosen c ON c.canonical=regexp_replace(lower(s.domain),'^www\.','')
